use agentfx_script::{parse,timing,lower,ir::Ch};
use std::{collections::HashMap,path::Path};
fn compile(src:&str)->lower::Compiled {let (doc,errors)=parse::parse(src);assert!(errors.is_empty(),"{errors:?}");let (tl,errors)=timing::solve(&doc,&HashMap::new(),None);assert!(errors.is_empty(),"{errors:?}");lower::compile(&doc,&tl,None,Path::new(env!("AGENTFX_ROOT")))}
const DROP:&str="video \"test\" size=1920x1080 fps=30 captions=off\nscene a dur=6s\n  rect #ball x=100 y=100 w=80 h=80 fill=#FFFFFF\n  @0s drop #ball bounce=0.2\n";
#[test] fn deterministic_tracks_and_settle_no_keys() {let a=compile(DROP);assert!(a.diags.iter().all(|d|d.severity!=agentfx_script::diag::Severity::Error),"{:?}",a.diags);let b=compile(DROP);assert_eq!(serde_json::to_string(&a.ir.tracks).unwrap(),serde_json::to_string(&b.ir.tracks).unwrap());let y=a.ir.tracks.iter().find(|t|t.layer.contains("ball") && t.ch==Ch::Y).unwrap();assert!(y.keys.last().unwrap().t<5.);assert!((y.eval(6.).n()-900.).abs()<0.1);}
#[test] fn bad_parameters_use_physics_diagnostic() {for command in ["drop #missing","drop #ball bounce=2","drop #ball gravty=3","drop #ball into #missing","shatter #ball pieces=0"] {let c=compile(&DROP.replace("drop #ball bounce=0.2",command));assert!(c.diags.iter().any(|d|d.code=="E_PHYSICS"),"{command}: {:?}",c.diags);}}
#[test] fn fracture_and_rewind() {let src=DROP.replace("drop #ball bounce=0.2","shatter #ball pieces=8 seed=7 force=200 walls=none dur=2s\n  @2s rewind #ball speed=1 dur=2s");let a=compile(&src);assert!(a.diags.iter().all(|d|d.severity!=agentfx_script::diag::Severity::Error),"{:?}",a.diags);let b=compile(&src);assert_eq!(serde_json::to_string(&a.ir.tracks).unwrap(),serde_json::to_string(&b.ir.tracks).unwrap());let tracks:Vec<_>=a.ir.tracks.iter().filter(|t|t.layer.contains("shard") && t.ch==Ch::X).collect();assert_eq!(tracks.len(),8);for t in tracks {assert!((t.eval(0.5).n()-t.eval(3.5).n()).abs()<0.1);}}
#[test] fn examples_compile_clean_and_stay_in_frame() {for f in ["physics","shatter"] {let src=std::fs::read_to_string(format!("{}/examples/features/{f}.reel",env!("AGENTFX_ROOT"))).unwrap();let a=compile(&src);assert!(a.diags.iter().all(|d|d.severity!=agentfx_script::diag::Severity::Error),"{f}: {:?}",a.diags);let b=compile(&src);assert_eq!(serde_json::to_string(&a.ir.tracks).unwrap(),serde_json::to_string(&b.ir.tracks).unwrap());}}
#[test] fn spin_scatter_validated() {for command in ["drop #ball spin=abc","drop #ball scatter=x"] {let c=compile(&DROP.replace("drop #ball bounce=0.2",command));assert!(c.diags.iter().any(|d|d.code=="E_PHYSICS"),"{command}");}}
